UPDATE _fodynest_schema_tmp SET s = s || '{"locale":"it","nx_ui_lang":"it","nx_choice_cards":true,"goNextPageAutomatic":true,"allowCompleteSurveyAutomatic":false,"textUpdateMode":"onTyping","showProgressBar":"off","showQuestionNumbers":"off","questionsOnPageMode":"standard","requiredText":"*","pagePrevText":"Indietro","pageNextText":"Avanti","completeText":"Invia le risposte","nx_paradata":true,"nx_no_client_meta":true,"nx_coarse_device":true,"nx_no_probe":["n2_2","n2_3","n2_4","n2_5"],"pages":[{"name":"intro","elements":[{"type":"html","name":"intro_testo","html":"<p style=\"margin:0 0 12px;line-height:1.55\">Questo questionario fa parte di uno studio su FODYNEST.</p><p style=\"margin:0 0 12px;line-height:1.55\">Lo studio confronta <strong style=\"color:#286181\">che cosa chi ha fatto il gioco vuole trasmettere</strong> con che cosa arriva davvero a chi ci gioca.</p><p style=\"margin:0 0 12px;line-height:1.55\">Non ci sono risposte giuste: ci interessa che cosa pensi tu. Meglio frasi concrete che formule generali.</p><p style=\"margin:0 0 12px;line-height:1.55\"><strong style=\"color:#286181\">Rispondi senza consultarti con l&#x27;altra designer e le persone di FODY.</strong> Anche le differenze tra le vostre risposte sono un dato.</p><p style=\"margin:0 0 12px;line-height:1.55\">Ci vogliono circa 30-40 minuti. Puoi interrompere e riprendere: le risposte restano salvate su questo dispositivo per 14 giorni.</p><p style=\"margin:0 0 12px;line-height:1.55\">Cosa succede alle risposte:</p><ul style=\"list-style:disc outside;margin:0 0 14px;padding-left:1.3em;line-height:1.55\"><li style=\"margin:0 0 6px\">vengono depositate così come sono nella preregistrazione dello studio su OSF, che a fine studio diventa pubblica;</li><li style=\"margin:0 0 6px\">possono essere citate nel paper;</li><li style=\"margin:0 0 6px\"><strong style=\"color:#286181\">non sono anonime</strong>, perché il gioco e chi lo ha fatto sono noti;</li><li style=\"margin:0 0 6px\">la piattaforma registra anche il tempo passato su ogni pagina e il tipo di dispositivo (telefono, tablet o computer).</li></ul><p style=\"margin:0 0 12px;line-height:1.55\">Partecipare è libero e puoi ritirarti quando vuoi.</p><p style=\"margin:0 0 12px;line-height:1.55\">Ricerca di NexLudica APS. Responsabile: Vittorio Guerrieri.</p>"},{"type":"boolean","name":"consent_partecipazione","renderAs":"checkbox","titleLocation":"hidden","title":"Ho letto queste informazioni e accetto di partecipare e che le mie risposte siano usate come descritto.","label":"Ho letto queste informazioni e accetto di partecipare e che le mie risposte siano usate come descritto.","isRequired":true,"requiredErrorText":"Per andare avanti spunta la casella."}],"title":"Prima di iniziare"},{"name":"p_chi","elements":[{"type":"radiogroup","name":"chi_compila","title":"Chi sta compilando?","choices":[{"value":1,"text":"Letizia Vaccarella"},{"value":2,"text":"Giulia Teverini"}],"isRequired":true,"requiredErrorText":"Questa risposta serve per andare avanti."}],"title":"Chi compila"},{"name":"p_n1","elements":[{"type":"comment","name":"n1","title":"Immagina una persona che ha appena finito una partita a FODYNEST. Se dovesse dire in una frase che cosa le ha lasciato il gioco, quale frase vorresti sentire?","rows":5,"autoGrow":true,"allowResize":false}],"title":"Che cosa vuoi trasmettere"},{"name":"p_n2","elements":[{"type":"panel","name":"n2_panel","title":"Elenca fino a cinque cose (idee, conoscenze, atteggiamenti) che vorresti arrivassero a chi gioca, in ordine di importanza.","description":"Una per casella: appena ne scrivi una, compare la casella per la successiva.","elements":[{"type":"comment","name":"n2_1","title":"Prima cosa","rows":2,"autoGrow":true,"allowResize":false},{"type":"comment","name":"n2_2","title":"Seconda cosa","rows":2,"autoGrow":true,"allowResize":false,"visibleIf":"{n2_1} notempty"},{"type":"comment","name":"n2_3","title":"Terza cosa","rows":2,"autoGrow":true,"allowResize":false,"visibleIf":"{n2